// This file is automatically generated and enhanced for lock stability.
import { createClient } from '@supabase/supabase-js';
import type { Database } from './types';

const SUPABASE_URL = import.meta.env.VITE_SUPABASE_URL;
const SUPABASE_PUBLISHABLE_KEY = import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY;

export const supabase = createClient<Database>(SUPABASE_URL, SUPABASE_PUBLISHABLE_KEY, {
  auth: {
    storage: typeof window !== 'undefined' ? window.localStorage : undefined,
    persistSession: true,
    autoRefreshToken: true,
    detectSessionInUrl: true,
    // Pass-through lock to prevent NavigatorLockAcquireTimeoutError in React Strict Mode & concurrent components
    lock: async (_name: string, _acquireTimeout: number, fn: () => Promise<any>) => await fn(),
  }
});
